package com.spaceagent.platform.runtime.domain;
import java.util.Objects;
/** Pure no-effect comparison of deterministic and provider candidate command proposals. */
public record SupervisorShadowComparison(Outcome outcome,String deterministicKind,String providerKind,boolean providerCandidateExecuted){public enum Outcome{MATCH,COMMAND_KIND_MISMATCH,INPUT_HASH_MISMATCH,UNKNOWN_CANDIDATE}public SupervisorShadowComparison{outcome=Objects.requireNonNull(outcome);if(deterministicKind==null||deterministicKind.isBlank())throw new IllegalArgumentException("deterministicKind");if(providerCandidateExecuted)throw new IllegalArgumentException("shadow cannot execute provider candidate");}public static SupervisorShadowComparison classify(String deterministicKind,String deterministicInputHash,String providerKind,String providerInputHash,boolean providerUnknown){if(providerUnknown)return new SupervisorShadowComparison(Outcome.UNKNOWN_CANDIDATE,deterministicKind,providerKind,false);if(!Objects.equals(deterministicKind,providerKind))return new SupervisorShadowComparison(Outcome.COMMAND_KIND_MISMATCH,deterministicKind,providerKind,false);if(!Objects.equals(deterministicInputHash,providerInputHash))return new SupervisorShadowComparison(Outcome.INPUT_HASH_MISMATCH,deterministicKind,providerKind,false);return new SupervisorShadowComparison(Outcome.MATCH,deterministicKind,providerKind,false);}}
